parameters.jsCode:
// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($env.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($env.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

// Two populations that look identical in the orders table:
//
//   critical  A verified payment.succeeded exists in payment_events, but the
//             order is still pending. The webhook took the money and did not
//             publish. A paying customer is holding an invitation they cannot
//             share, and nothing else in the system notices — the webhook only
//             log.warn()s, which goes to PostHog, which nobody watches at 2am.
//
//   info      Pending with no webhook delivery at all. Almost always an
//             abandoned checkout. Claimed, counted, never alerted.
const critical = d.severity === 'critical';
const heading = critical ? 'Paid order did not publish' : 'Order pending';
const cta = site + '/admin/invitations';

const bodyHtml = `
  ${critical ? `<div style="background:#fff1ef;border-left:3px solid ${brand};padding:12px 16px;border-radius:6px;margin:0 0 18px;color:#7a2a24;">
      The provider confirmed <strong>payment.succeeded</strong> for this order, but it is still
      <strong>pending</strong> and the invitation is <strong>${esc(d.event_status)}</strong>.
      Someone has paid and cannot share their invitation.
    </div>` : ''}
  <ul style="margin:0 0 14px;padding-left:18px;">
    <li>Order <code>${esc(d.order_id)}</code></li>
    <li>${esc(d.title)} \u2014 <a href="${site}/invite/${esc(d.slug)}" style="color:${brand};">/invite/${esc(d.slug)}</a></li>
    <li>${esc(d.plan_code)} \u00b7 ${inr(d.amount_inr)} \u00b7 ${esc(d.provider)}</li>
    <li>Buyer ${esc(d.buyer_email_masked || '\u2014')}</li>
    <li>Pending ${d.minutes_pending} minutes (created ${esc(d.created_ist)} IST)</li>
    ${d.provider_payment_id ? '<li>Provider payment id: <code>' + esc(d.provider_payment_id) + '</code></li>' : ''}
    ${d.failure_reason ? '<li>Failure reason: ' + esc(d.failure_reason) + '</li>' : ''}
  </ul>
  ${critical ? '<p style="margin:0;font-size:14px;color:#6b615e;">To resolve: confirm the payment in the provider dashboard, then replay the webhook delivery. The handler is idempotent on (provider, event_id), so replaying is the safest fix.</p>' : ''}`;

return { json: {
  dedupe_key: d.dedupe_key,
  to: '',
  severity: d.severity,
  stored: {
    order_id: d.order_id, event_id: d.event_id, slug: d.slug, title: d.title,
    severity: d.severity, amount_inr: d.amount_inr, plan_code: d.plan_code,
    minutes_pending: d.minutes_pending, event_status: d.event_status,
    webhook_event_type: d.webhook_event_type, dedupe_key: d.dedupe_key,
    subject: (critical ? '[CRITICAL] ' : '') + heading + ' \u2014 ' + d.title + ' (' + inr(d.amount_inr) + ')',
    whatsapp: critical
      ? 'CRITICAL \u2014 payment confirmed but order ' + String(d.order_id).slice(0, 8)
        + ' is still pending. ' + d.title + ', ' + inr(d.amount_inr) + ', invitation is '
        + d.event_status + '. ' + cta
      : 'Order pending ' + d.minutes_pending + 'm \u2014 ' + d.title + ', ' + inr(d.amount_inr)
        + ', no webhook delivery. Likely abandoned checkout. ' + site + '/admin',
    html: shell(heading, bodyHtml, 'Open admin', cta, null),
    text: heading + '\nOrder ' + d.order_id + '\n' + d.title + ' \u2014 ' + inr(d.amount_inr)
      + '\nPending ' + d.minutes_pending + 'm\n' + cta,
  },
} };

